function renderReleases(){const c=$("pageContent");c.replaceChildren();if(!admin()){c.append(empty("Release approval and public publishing are reserved for the CEO and Vice Administrator."));return}const panel=card("Leadership release queue","Review submitted builds, leave notes, approve or reject, then publish only approved releases.");const list=el("div","page-list");const pending=state.builds.filter(b=>["submitted","approved","rejected","published"].includes(b.status));if(!pending.length)list.append(empty("There are no builds in the release queue."));pending.forEach(b=>{const actions=[];const note=el("input","page-inline-input");note.placeholder="Review note (optional)";note.setAttribute("aria-label","Review note for "+b.version);if(b.status==="submitted"){actions.push(btn("Approve",async()=>{await call({action:"review-build",id:b.id,decision:"approved",review_note:note.value});await reload();render()}));actions.push(btn("Reject",async()=>{await call({action:"review-build",id:b.id,decision:"rejected",review_note:note.value});await reload();render()},"page-button danger"))}if(b.status==="approved")actions.push(btn("Publish public release",async()=>{if(!confirm("Publish "+b.version+" as a public download?"))return;await call({action:"review-build",id:b.id,decision:"published",review_note:note.value});await reload();render()}));actions.unshift(note);list.append(row((b.product?.name||productName(b.product_id))+" · "+b.version,b.title+" — "+(b.description||"No build description."),[pill(b.status),b.file_name||"Package file",fmt(b.submitted_at),b.review_note||""].filter(Boolean),actions))});panel.append(list);c.append(panel)}
function renderMessages(){const c=$("pageContent");c.replaceChildren();if(!admin()&&!assigned("support_inbox")){c.append(empty("Product messages and the support inbox are available to the CEO, Vice Administrator, and staff explicitly assigned to support."));return}const panel=card("Product messages & support inbox","Messages and feedback received from company products. Review the product, sender, and message details.");const list=el("div","page-list");const rows=(state.messages||[]).slice().sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));if(!rows.length)list.append(empty("No product messages are available in your support inbox yet."));rows.forEach(m=>{const product=m.product?.name||productName(m.product_id);const sender=m.sender_name||m.name||m.sender_email||m.email||"Product user";const subject=m.subject||m.title||m.topic||"Product message";const body=m.body||m.message||m.content||m.description||"No message text was supplied.";const meta=[product,sender,fmt(m.created_at)];if(m.status)meta.push(pill(m.status));if(m.email&&m.email!==sender)meta.push(m.email);list.append(row(subject,body,meta))});panel.append(list);c.append(panel)}
async function exitCall(body){const {data,error}=await client.functions.invoke("zakitech-staff-exit",{body});if(error){let message=error.message||"Request failed.";try{if(error.context&&typeof error.context.json==="function"){const b=await error.context.json();message=b.error||message}}catch(_){}throw Error(message)}if(data?.error)throw Error(data.error);return data}
async function loadExitRequests(container){container.replaceChildren();container.append(el("p","muted","Loading pending departure requests…"));try{const data=await exitCall({action:"list-pending"});container.replaceChildren();if(!data.requests.length){container.append(empty("There are no pending staff departure requests."));return}data.requests.forEach(r=>{const content="Requested by "+r.requester_display_name+" (@"+r.requester_username+") · "+human(r.requester_role)+"\nSubmitted "+fmt(r.created_at)+"\n\n"+r.letter;const item=row(r.requester_display_name+" — @"+r.requester_username,content,[pill("pending"),fmt(r.created_at)]);item.querySelector(".page-row-copy p").style.whiteSpace="pre-wrap";item.querySelector(".page-row-copy p").style.overflowWrap="anywhere";item.querySelector(".page-row-copy p").style.maxWidth="800px";const approve=btn("Approve & delete account",async()=>{const response=window.prompt("Optional note to attach to the approval:","Approved by the company administrator.");if(response===null)return;if(!confirm("FINAL CONFIRMATION: This permanently deletes "+r.requester_username+"'s authentication account and profile. They will lose access and must receive a new invitation to return. Continue?"))return;approve.disabled=true;try{const result=await exitCall({action:"review",request_id:r.id,decision:"approved",admin_response:response});notice(result.message);await loadExitRequests(container)}catch(e){notice(e.message,true);approve.disabled=false}},"page-button danger");const reject=btn("Reject request",async()=>{const response=window.prompt("Explain why this request is rejected. The staff account will remain active:","");if(response===null)return;if(response.trim().length<3){notice("Please provide a short explanation.",true);return}reject.disabled=true;try{const result=await exitCall({action:"review",request_id:r.id,decision:"rejected",admin_response:response});notice(result.message);await loadExitRequests(container)}catch(e){notice(e.message,true);reject.disabled=false}},"page-button secondary");item.querySelector(".page-actions")?.remove();const actions=el("div","page-actions");actions.append(approve,reject);item.append(actions);container.append(item)})}catch(e){container.replaceChildren(empty(e.message));notice(e.message,true)}}
function renderLeaveCompany(){const c=$("pageContent");c.replaceChildren();const role=state.profile?.role;if(["owner","vice_admin"].includes(role)){c.append(card("Administrator account","Administrator accounts cannot be removed through the staff departure request workflow. Contact the company owner for a governed leadership transition."));return}const intro=card("Request to leave the company","You cannot delete your ZakiTech account yourself. Write a formal letter explaining why you want to leave, including any complaints or concerns. Your account remains active while the authorized administrator reviews the request.");intro.append(el("p","muted","After approval, your account and sign-in identity will be deleted. You will no longer be able to access the company workspace. To return later, an administrator must send you a new invitation."));c.append(intro);const form=formCard("Write your departure letter","Include your reason for leaving and any concerns you want the administrator to consider. Minimum 30 characters.",[{label:"Letter / reason for leaving",name:"letter",type:"textarea",required:true,full:true}], "Submit departure request",async v=>{if(v.letter.trim().length<30)throw Error("Please write at least 30 characters.");const result=await exitCall({action:"submit",letter:v.letter});notice(result.message);await renderMyExitRequests(historyList)});const textarea=form.querySelector("textarea");if(textarea){textarea.minLength=30;textarea.maxLength=12000;textarea.rows=7;textarea.placeholder="Dear Administrator,\n\nI am writing to formally request to leave the company…\n\nReason(s) and concerns:\n\nYours sincerely,"}c.append(form);const history=card("My departure requests","Track the status of letters you have submitted.");const historyList=el("div","page-list");history.append(historyList);c.append(history);renderMyExitRequests(historyList)}
