async function renderAttendance(){
 const c=$("pageContent");c.replaceChildren();
 const receptionist=state.profile?.role==="receptionist";
 const intro=card("Attendance & check-in","Record your workday start and finish. Check-in records are timestamped by the company system and visible to authorized company leadership and reception.");const links=el("div","page-actions");links.append(anchor("Staff accounts","staff-accounts.html"));intro.append(links);c.append(intro);
 let mine=null,date=null;try{const r=await call({action:"my-attendance"});mine=r.attendance;date=r.date}catch(e){c.append(empty(e.message));return}
 const today=card("My workday",date+" · Africa/Kampala time");const grid=el("div","page-grid");const checkIn=card("Check-in",mine?fmt(mine.checked_in_at):"Not checked in yet");checkIn.append(el("p","muted",mine?.checkin_note||"Your workday starts when you check in."));
 const checkOut=card("Check-out",mine?.checked_out_at?fmt(mine.checked_out_at):mine?"Still checked in":"Available after check-in");checkOut.append(el("p","muted",mine?.checkout_note||"Check out when your workday ends."));
 grid.append(checkIn,checkOut);today.append(grid);
 const noteLabel=field("Optional note","attendance_note","text","","",null);today.append(noteLabel);
 if(!mine){today.append(btn("Check in now",async()=>{try{await call({action:"check-in",note:noteLabel.querySelector("input").value});notice("Your check-in has been recorded.");await renderAttendance()}catch(e){notice(e.message,true)}}))}
 else if(mine.status==="checked_in"){today.append(btn("Check out now",async()=>{try{await call({action:"check-out",note:noteLabel.querySelector("input").value});notice("Your check-out has been recorded.");await renderAttendance()}catch(e){notice(e.message,true)}}))}
 else today.append(el("p","page-empty","Your attendance for today is complete."));
 c.append(today);
 if(admin()||receptionist){
  const report=card("Team attendance","Review staff check-ins and check-outs. Receptionists can help maintain attendance records; company administrators can review team activity.");const controls=el("div","page-actions");const dateInput=field("Filter by date (optional)","attendance_date","date","",false);const load=btn("Load attendance",()=>loadAttendanceRows(list,dateInput.querySelector("input").value));controls.append(dateInput,load);report.append(controls);const list=el("div","page-list");report.append(list);c.append(report);await loadAttendanceRows(list,"");
 }
}
async function loadAttendanceRows(container,date){
 container.replaceChildren();try{const result=await call({action:"list-attendance",date:date||""}),records=result.records||[];if(!records.length){container.append(empty("No attendance records found for this date."));return}const dateParts=new Intl.DateTimeFormat("en-CA",{timeZone:"Africa/Kampala",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date());const today=dateParts.find(x=>x.type==="year").value+"-"+dateParts.find(x=>x.type==="month").value+"-"+dateParts.find(x=>x.type==="day").value;
 records.forEach(record=>{const person=record.staff||{},name=person.display_name||person.username||"Staff member";const meta=[pill(record.status),record.work_date,"In: "+fmt(record.checked_in_at),record.checked_out_at?"Out: "+fmt(record.checked_out_at):"Not checked out"];const actions=[];if(record.status==="checked_in"&&record.work_date===today&&(admin()||state.profile?.role==="receptionist"))actions.push(btn("Record check-out",async()=>{if(!confirm("Record check-out for "+name+"?"))return;try{await call({action:"check-out",user_id:record.user_id,note:"Recorded by company reception/administration."});notice("Check-out recorded for "+name+".");await renderAttendance()}catch(e){notice(e.message,true)}},"page-button"));const r=row(name,"@"+(person.username||"unknown")+" · "+(names[person.role]||person.role||"Staff"),meta,actions);const icon=r.querySelector(".page-row-icon");if(person.avatar_url){const img=el("img","staff-avatar");img.src=person.avatar_url;img.alt=name+" profile photo";icon.replaceChildren(img);icon.classList.add("has-avatar")}container.append(r)})
 }catch(e){container.append(empty("Could not load attendance: "+e.message))}
}
